<?php
require "auth.php";require_admin();$page_title="Dashboard Admin";
if(isset($_POST["add_menu"])){ $nama=trim($_POST["nama"]);$harga=(int)$_POST["harga"];$kat=trim($_POST["kategori"]);$gambar="assets/poster.jpg";$st=$conn->prepare("INSERT INTO menu(nama,harga,kategori,gambar,status) VALUES(?,?,?,?,1)");$st->bind_param("siss",$nama,$harga,$kat,$gambar);$st->execute();header("Location: admin.php?ok=menu");exit;}
if(isset($_GET["delete_menu"])){$id=(int)$_GET["delete_menu"];$conn->query("UPDATE menu SET status=0 WHERE id=$id");header("Location: admin.php");exit;}
if(isset($_POST["update_menu"])){$id=(int)$_POST["id"];$nama=trim($_POST["nama"]);$harga=(int)$_POST["harga"];$kat=trim($_POST["kategori"]);$st=$conn->prepare("UPDATE menu SET nama=?,harga=?,kategori=? WHERE id=?");$st->bind_param("sisi",$nama,$harga,$kat,$id);$st->execute();header("Location: admin.php?ok=update");exit;}
$menuCount=$conn->query("SELECT COUNT(*) c FROM menu WHERE status=1")->fetch_assoc()["c"];
$userCount=$conn->query("SELECT COUNT(*) c FROM users WHERE role='user'")->fetch_assoc()["c"];
$trxCount=$conn->query("SELECT COUNT(*) c FROM transaksi")->fetch_assoc()["c"];
$sales=$conn->query("SELECT COALESCE(SUM(total),0) t FROM transaksi WHERE DATE(created_at)=CURDATE()")->fetch_assoc()["t"];
$menus=$conn->query("SELECT * FROM menu WHERE status=1 ORDER BY id DESC");
$tr=$conn->query("SELECT t.*,u.nama user_nama FROM transaksi t LEFT JOIN users u ON u.id=t.user_id ORDER BY t.id DESC LIMIT 50");
require "header.php";
?>
