<div class="stats"><div><span>Penjualan Hari Ini</span><b><?=rupiah($sales)?></b></div><div><span>Menu Aktif</span><b><?=$menuCount?></b></div><div><span>Total User</span><b><?=$userCount?></b></div><div><span>Total Transaksi</span><b><?=$trxCount?></b></div></div>
