<div id="editBox" class="card edit-box" style="display:none"><span class="mini-label">EDIT MENU</span><h3>Ubah Data Menu</h3><form method="post"><input type="hidden" name="update_menu" value="1"><input type="hidden" id="editId" name="id"><label>Nama<input id="editNama" name="nama" required></label><label>Harga<input id="editHarga" type="number" name="harga" required></label><label>Kategori<input id="editKategori" name="kategori"></label><button class="btn btn-primary">Simpan Perubahan</button> <button type="button" class="btn btn-light" onclick="document.getElementById('editBox').style.display='none'">Batal</button></form></div>
<div class="card table-wrap"><div class="panel-title"><div><span class="mini-label">TRANSAKSI</span><h3>Riwayat Penjualan</h3></div><a class="btn btn-outline" href="export.php">Export</a></div><table><thead><tr><th>Kode</th><th>Pelanggan</th><th>User</th><th>Metode</th><th>Total</th><th>Waktu</th></tr></thead><tbody><?php while($r=$tr->fetch_assoc()):?><tr><td><?=e($r["kode"])?></td><td><?=e($r["pelanggan"])?></td><td><?=e($r["user_nama"]??"-")?></td><td><?=e($r["metode"])?></td><td><?=rupiah($r["total"])?></td><td><?=e($r["created_at"])?></td></tr><?php endwhile;?></tbody></table></div></section>
<script>
function editMenu(m){document.getElementById('editBox').style.display='block';document.getElementById('editId').value=m.id;document.getElementById('editNama').value=m.nama;document.getElementById('editHarga').value=m.harga;document.getElementById('editKategori').value=m.kategori;document.getElementById('editBox').scrollIntoView({behavior:'smooth'});}
</script>
